import unittest
from candidate import below_threshold

class TestBelowThreshold(unittest.TestCase):
    def test_below_threshold_all_below(self):
        self.assertTrue(below_threshold([1, 2, 3], 5))

    def test_below_threshold_all_negative(self):
        self.assertTrue(below_threshold([-1, -2, -3], 0))

    def test_below_threshold_mixed_numbers(self):
        self.assertTrue(below_threshold([-5, 0, 2], 3))
        self.assertFalse(below_threshold([-5, 0, 4], 3))

    def test_below_threshold_empty_list(self):
        self.assertTrue(below_threshold([], 10))

    def test_below_threshold_single_element_below(self):
        self.assertTrue(below_threshold([42], 50))
        self.assertFalse(below_threshold([50], 42))

    def test_below_threshold_single_element_equal(self):
        self.assertFalse(below_threshold([5], 5))

    def test_below_threshold_threshold_matched(self):
        self.assertFalse(below_threshold([10], 10))

    def test_below_threshold_threshold_exceeded(self):
        self.assertFalse(below_threshold([10, 20], 15))

    def test_below_threshold_floats(self):
        self.assertTrue(below_threshold([1.5, 2.5], 3.0))
        self.assertFalse(below_threshold([3.0, 2.5], 2.5))

    def test_below_threshold_threshold_float(self):
        self.assertFalse(below_threshold([1.1], 1.0))
        self.assertTrue(below_threshold([0.9], 1.0))

    def test_below_threshold_non_integer_threshold(self):
        self.assertTrue(below_threshold([1.5, 2.5], 3.0))
        self.assertTrue(below_threshold([1.5, 2.5], 2.5))

    def test_below_threshold_non_numeric_elements(self):
        with self.assertRaises(TypeError):
            below_threshold([1, "2", 3], 5)
        with self.assertRaises(TypeError):
            below_threshold([1, 2, None], 5)

    def test_below_threshold_non_list_input(self):
        with self.assertRaises(TypeError):
            below_threshold("not a list", 5)
        with self.assertRaises(TypeError):
            below_threshold(5, 10)

    def test_below_threshold_non_integer_threshold_type(self):
        with self.assertRaises(TypeError):
            below_threshold([1, 2, 3], "10")
        with self.assertRaises(TypeError):
            below_threshold([1, 2, 3], 10.5)

    def test_below_threshold_threshold_negative(self):
        self.assertTrue(below_threshold([-10, -5], -2))
        self.assertFalse(below_threshold([-1, -2], -3))

if __name__ == '__main__':
    unittest.main()
